INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:d72479327555','بخشنامه','بخشنامه ۱۷۹۴۰','۱۳۸۴/۱۰/۱۲','تعریف کتمان درآمد و هزینه غیرواقعی','درآمد کتمان‌شده: درآمدی که مؤدی در یک سال مالیاتی کسب کرده اما در دفاتر قانونی ثبت و در اظهارنامه ابراز نکرده است. هزینه غیرواقعی: هزینه ثبت‌شده در دفاتر که صوری، محقق‌نشده یا مستند به مدارک غیرواقعی است. در روش علی‌الرأس، درآمد تخمینی بدون اتکا به مدرک مشمول جریمه کتمان نیست.','https://www.intamedia.ir/','سازمان امور مالیاتی کشور (علی‌اکبر عرب‌مازار)','تعریف اولیه؛ بخشی از استناد آن (ثبت/عدم ثبت در دفاتر به‌عنوان معیار) با دادنامه ۱۴۰۰/۱۲/۰۳ دیوان عدالت اداری از حیز اعتبار ساقط شد.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:5ce7e288ac87','بخشنامه','دستورالعمل ۲۰۰/۹۹/۵۲۲','۱۳۹۹/۱۱/۲۷','دستورالعمل حسابرسی مالیاتی','دستورالعمل تبیین انواع و ترتیبات حسابرسی مالیاتی (موضوع مواد ۲۹ و ۴۱ آیین‌نامه اجرایی ماده ۲۱۹). بند ۴ آن به «کتمان درآمد یا فعالیت» اختصاص دارد و در «تذکر ۱» ذیل آن، محاسبه جریمه ماده ۱۹۲ به بخشنامه ۱۷۹۴۰ ارجاع داده شده بود.','https://www.intamedia.ir/','رئیس کل سازمان امور مالیاتی کشور','اطلاق تذکر ۱ بند ۴ (ارجاع به بخشنامه ۱۷۹۴۰) با دادنامه شماره ۱۴۰۰۰۹۹۷۰۹۰۵۸۱۳۱۶۸ ابطال شد.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:d26c6ac292ce','بخشنامه','دستورالعمل ۲۰۰/۹۹/۱۶','۱۳۹۹/۰۱/۳۱','دستورالعمل رسیدگی به تراکنش بانکی','نحوه بررسی و رسیدگی به اطلاعات پولی و مالی واصله از جمله تراکنش‌های بانکی مشکوک؛ تشکیل کمیته ویژه در هر اداره کل؛ تأکید بر اینکه صرف اقلام پولی وارده به حساب بانکی دلیلی بر وجود درآمد نیست.','https://www.intamedia.ir/','سازمان امور مالیاتی کشور','مبنای استنادی رأی‌های بعدی دیوان عدالت اداری در خصوص عدم کفایت صرف تراکنش بانکی برای اثبات کتمان درآمد.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:13d51d19a0b4','بخشنامه','بخشنامه ۲۰۰/۵۵۴۹/ص','۱۴۰۱/۰۳/۲۶','بخشنامه رسیدگی به تراکنش بانکی','تأکید مجدد بر اینکه اطلاعات حساب‌های بانکی فی‌نفسه مؤید درآمد اشخاص نیست مگر با اسناد، مدارک و قرائن مثبته درآمدی‌بودن آن احراز شود. بند ۴ آن، حساب‌های متصل به شبکه شاپرک را پیش‌فرض «حساب فروش» تلقی کرده بود.','https://www.intamedia.ir/','سازمان امور مالیاتی کشور','بند ۴ این بخشنامه با دادنامه‌های ۱۴۰۱۰۹۹۷۰۹۰۵۸۱۲۰۷۷ و ۱۴۰۱۰۹۹۷۰۹۰۵۸۱۲۰۷۸ (۱۴۰۱/۰۹/۲۲) دیوان عدالت اداری ابطال شد.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:a825849d6b2d','بخشنامه','بخشنامه ۲۱۰/۱۰۵۸/ص','۱۴۰۱/۰۱/۲۴','ابلاغ رأی دیوان عدالت اداری','ارسال تصویر دادنامه هیأت عمومی دیوان عدالت اداری شماره ۱۴۰۰۰۹۹۷۰۹۰۵۸۱۳۱۶۸ (مورخ ۱۴۰۰/۱۲/۰۳) به ادارات کل امور مالیاتی سراسر کشور جهت رعایت مفاد رأی مذکور در محاسبه و مطالبه جرایم کتمان درآمد.','https://www.intamedia.ir/','سازمان امور مالیاتی کشور','بخشنامه ابلاغی، نه بخشنامه تفسیری مستقل؛ صرفاً ناقل رأی دیوان است.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:352cdf188597','بخشنامه','دادنامه ۱۴۰۰۰۹۹۷۰۹۰۵۸۱۳۱۶۸','۱۴۰۰/۱۲/۰۳','رأی هیأت عمومی دیوان عدالت اداری','ابطال اطلاق «تذکر ۱ بند ۴» دستورالعمل ۲۰۰/۹۹/۵۲۲. طبق این رأی، پس از اصلاح ماده ۱۹۲ در سال ۱۳۹۴، «عدم ثبت در دفاتر» دیگر شرط تحقق کتمان درآمد نیست؛ صرف عدم ابراز درآمد در اظهارنامه، مشمول جریمه غیرقابل‌بخشودگی ماده ۱۹۲ است.','https://www.intamedia.ir/','هیأت عمومی دیوان عدالت اداری','مهم‌ترین رأی تفسیری اخیر در این موضوع؛ معیار «کتمان درآمد» را از «عدم ثبت در دفاتر» به «عدم ابراز در اظهارنامه» تغییر داد.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:7a05b827687f','بخشنامه','دادنامه‌های ۱۴۰۱۰۹۹۷۰۹۰۵۸۱۲۰۷۷ و ۱۴۰۱۰۹۹۷۰۹۰۵۸۱۲۰۷۸','۱۴۰۱/۰۹/۲۲','رأی هیأت عمومی دیوان عدالت اداری','ابطال بند ۴ بخشنامه ۲۰۰/۵۵۴۹/ص. رأی تصریح می‌کند صرف انجام تراکنش‌های بانکی جنبه درآمدی ندارد و بار اثبات درآمدی‌بودن آن (طبق بندهای ۱۱ و ۱۸ دستورالعمل ۲۰۰/۹۹/۱۶) بر عهده مأموران مالیاتی است، نه مؤدی.','https://www.intamedia.ir/','هیأت عمومی دیوان عدالت اداری','استناد پرکاربرد در اعتراض به برگ تشخیص مبتنی بر صرف تراکنش بانکی.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:3c3f1a43529c','بخشنامه','دادنامه‌های ۱۱۵۱ الی ۱۱۵۲','۱۳۹۹/۱۲/۱۷','رأی هیأت عمومی دیوان عدالت اداری','وصول مالیات صرفاً بر مبنای تراکنش‌های بانکی، بدون اظهارات مکتوب و بررسی مستندات مؤدی، فاقد وجاهت قانونی اعلام شده است.','https://www.intamedia.ir/','هیأت عمومی دیوان عدالت اداری','مؤید و هم‌راستا با دستورالعمل ۲۰۰/۹۹/۱۶ (بندهای ۱، ۹، ۱۲ و ۱۸).','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:1ecb2bc85ed3','بخشنامه','دادنامه ۷۶۸','۱۳۹۱/۱۰/۱۸','رأی هیأت عمومی دیوان عدالت اداری','عدم ابطال بخشنامه شماره ۱۱۴۲۵/۱۱۱۱۵۰/۲۱۰ (۱۳۸۴/۰۶/۲۱) موضوع ماده ۲۰۲ در خصوص ممنوع‌الخروجی مدیران اشخاص حقوقی بابت بدهی مالیاتی (از جمله ناشی از کتمان درآمد) مربوط به دوران مدیریت آنان.','https://www.intamedia.ir/','هیأت عمومی دیوان عدالت اداری','موضوع جانبی (ماده ۲۰۲) اما مرتبط با پیگیری مالیاتِ درآمد کتمان‌شده اشخاص حقوقی.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:f5410b556407','بخشنامه','صورتجلسه (پیرو نامه ۲۱۰/۲۰/م)','۱۳۸۸/۰۵/۰۵','رأی شورای عالی مالیاتی','در خصوص اظهارنامه‌های مالی مغایر تسلیمی شرکت‌های پیمانکاری به معاونت برنامه‌ریزی (جهت رتبه‌بندی): رأی اکثریت مقرر می‌دارد احراز درآمد کتمان‌شده باید متکی به اسناد و مدارک مثبته، دلایل و اطلاعات کافی و با رعایت مرور زمان ماده ۱۵۷ باشد؛ صرف مغایرت دو اظهارنامه کافی نیست.','https://www.intamedia.ir/','هیأت عمومی شورای عالی مالیاتی','نظر اقلیت این احراز را در عمل غیرممکن دانسته بود؛ رأی اکثریت ملاک عمل قرار گرفت.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:98c90c603df9','بخشنامه','رأی ۲۰۱/۰۲۹','۱۳۹۲/۱۲/۲۰','رأی/نظریه شورای عالی مالیاتی','نظر تفصیلی در تبیین دقیق‌تر مفهوم «درآمد کتمان‌شده» موضوع قسمت اخیر ماده ۱۹۲ و تبصره ۱ ماده ۱۴۶ مکرر ق.م.م.','https://www.intamedia.ir/','هیأت عمومی شورای عالی مالیاتی','در دادنامه‌های بعدی دیوان عدالت اداری به‌عنوان مرجع تفسیری مورد استناد قرار گرفته است.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:01d489c6edc8','بخشنامه','نامه دفتر امور تشخیص مالیاتی','۱۴۰۳/۱۰/۱۱ (پاسخ به نامه ۱۴۰۳/۱۰/۰۳)','نظریه اداری / نامه فنی','انحراف در مصرف مواد اولیه (ضایعات ناشی از نوع صنعت، فناوری، کارگر غیرماهر، ماشین‌آلات مستعمل و...) الزاماً دلیل بر کتمان درآمد/فعالیت نیست؛ باید در چارچوب ماده ۱۴۷ و بند ۲۵ ماده ۱۴۸ بررسی و در صورت ضایعات غیرعادی، هزینه غیرقابل‌قبول تلقی شود.','https://www.intamedia.ir/','معاونت درآمدهای مالیاتی - دفتر امور تشخیص مالیاتی','پاسخ موردی به استعلام اداره کل آذربایجان غربی؛ فاقد شماره بخشنامه رسمی سراسری.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:4958d511be04','بخشنامه','نامه دفتر حسابرسی مالیاتی','۱۴۰۰/۰۶/۳۱','نظریه اداری / نامه فنی','در روش تبدیل اطلاعیه‌های خرید به فروش (بند ۳ نکات و ضوابط اجرایی ضرایب مالیاتی): تفاوت فروش محاسبه‌شده که مستند به قرائن غیرقابل‌تردید نباشد، «برآوردی» تلقی شده و کتمان درآمد محسوب نمی‌شود؛ فقط تفاوت مستند و اثبات‌شده مشمول جریمه ماده ۱۹۲ است.','https://www.intamedia.ir/','معاونت درآمدهای مالیاتی - دفتر حسابرسی مالیاتی','پاسخ موردی به استعلام اداره کل کرمانشاه.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('ماده۱۹۲_کتمان_درآمد:4a611d1b3406','بخشنامه','نامه دفتر فنی مالیاتی','۱۳۸۵/۰۶/۰۲','نظریه اداری / نامه فنی','در خصوص جریمه ماده ۱۹۲ بند «ب»: ارتباط تکلیف ارائه ترازنامه و حساب سود و زیان (موضوع اصلاح آیین‌نامه تبصره ۲ ماده ۹۵) با مشمولین بند «ب» ماده ۹۶/۹۵ که در تولید، خرید و فروش کالا فعالیت دارند؛ عدم ارائه آن مشمول جریمه ماده ۱۹۳ (نه لزوماً ماده ۱۹۲) است.','https://www.intamedia.ir/','دفتر فنی مالیاتی سازمان امور مالیاتی کشور','پاسخ موردی به استعلام اداره کل آذربایجان شرقی؛ بیشتر ناظر به ماده ۱۹۳ است اما در پرونده‌های کتمان درآمد کاربرد دارد.','ماده ۱۹۲',NULL,'ماده۱۹۲_کتمان_درآمد') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('قوانین‌مالیاتی:اشخاص حقوقی ۱۰۵-۱۱۸:00c6ccdbb287','بخشنامه','5126-17','1352/06/15','اظهارنظر مشورتي',NULL,'https://www.intamedia.ir/',NULL,NULL,'اشخاص حقوقی ۱۰۵-۱۱۸',NULL,'قوانین‌مالیاتی:اشخاص حقوقی ۱۰۵-۱۱۸') ON CONFLICT (source_id) DO NOTHING;
